function verify(signals) {
  const byDim = {};
  DIMENSIONS.forEach((d) => { byDim[d.key] = []; });
  signals.forEach((s) => { if (byDim[s.dim]) byDim[s.dim].push(s); });

  return DIMENSIONS.map((d) => {
    const list = byDim[d.key];
    const systems = Array.from(new Set(list.map((s) => s.system)));
    const posW = list.filter((s) => s.dir > 0).reduce((a, s) => a + s.strength, 0);
    const negW = list.filter((s) => s.dir < 0).reduce((a, s) => a + s.strength, 0);
    const totalW = posW + negW;

    if (totalW === 0) {
      return {
        key: d.key, name: d.name, verdict: 'none', verdictLabel: VERDICT_LABEL.none,
        agreementLabel: AGREEMENT_LABEL.none, systems: [], signals: [],
        question: d.question,
        note: '三个体系在这条维度上都没有给出明确倾向 —— 这本身也是信息：'
            + '说明该维度对这张盘不是显著特征，不必强行套一个类型。',
      };
    }

    const agree = Math.abs(posW - negW) / totalW;
    const dir = posW >= negW ? 1 : -1;
    const unanimous = posW === 0 || negW === 0;

    let verdict;
    if (systems.length < 2) verdict = 'single';
    else if (unanimous) verdict = 'converge';
    else verdict = 'diverge';

    const lean = dir > 0 ? d.positive : d.negative;

    let note;
    if (verdict === 'converge') {
      note = `${systems.join('、')}各自独立推导，都指向「${lean}」。`
           + '推导路径完全不同（历法干支 / 星曜落宫 / 天文位置）。'
           + '需要说明：实测三体系两两一致率约 48%，与随机无显著差异，'
           + `所以这【不构成】"该判断更可能为真"的证据。`
           + `它的实际用处是：同一个说法被两套不同的语言说出来了，`
           + `作为自省和对话的切入点，它更容易被记住和使用。`;
    } else if (verdict === 'diverge') {
      note = `体系之间指向不同（${list.map((s) => `${s.system}→${s.dir > 0 ? d.positive : d.negative}`).join('，')}）。`
           + '这不是"算错了"，而通常意味着该特质在你身上是【情境依赖】的 —— '
           + '面对不同环境会有不同反应，不适合用一个固定类型概括。'
           + '在这类维度上，"相左"本身比"一致"更有信息量，建议结合具体场景往下问。';
    } else {
      note = `只有${systems[0]}给出明确倾向（${lean}）。孤证不能作为判断依据，`
           + '但可以作为追问的切入点 —— 如果这条在你身上确实成立，那它值得单独展开。';
    }

    return {
      key: d.key, name: d.name,
      verdict, verdictLabel: VERDICT_LABEL[verdict],
      agreementLabel: AGREEMENT_LABEL[verdict],
      lean, dir, agreement: +agree.toFixed(3),
      systems,
      signals: list.map((s) => ({
        system: s.system,
        direction: s.dir > 0 ? d.positive : d.negative,
        dir: s.dir,
        z: s.z,
        strength: s.strength,
        basis: s.basis,
        citation: s.citation,
        detail: s.detail,
      })),
      question: d.question,
      note,
      probe: verdict === 'diverge'
        ? `在「${d.question}」这件事上，你觉得自己是稳定的，还是看情况而定？能举个最近的例子吗？`
        : null,
    };
  });
}

