    monthPillarConvention: {
      bazi: bazi.pillars[1].gz,
      ziwei: (ziwei.chineseDate || '').split(' ')[1] || null,
      same: bazi.pillars[1].gz === ((ziwei.chineseDate || '').split(' ')[1] || null),
      note: '八字月柱按节气分月，紫微月柱按农历月分月，二者定义不同，'
          + '不一致属正常，不代表任一实现有误。',
    },
    consistent: bazi.lunarText === ziwei.lunarDate,
    note: bazi.lunarText === ziwei.lunarDate
      ? '农历日期经两个独立库（lunar-javascript / iztro）交叉验证一致，历法层可信'
      : '⚠ 两个库给出的农历日期不一致，说明有一方历法实现有误，此盘不可信',
  };

  return {
    schema: 'mingli.fact/1',
    generatedAt: new Date().toISOString(),

    input: {
      y: mo.clock.y, m: mo.clock.m, d: mo.clock.d, h: mo.clock.h, mi: mo.clock.mi,
      gender: o.gender || '男',
      city: o.city || null,
      lonEast: mo.lonEast, lat: mo.lat,
      basis: mo.basis,
    },

