}

/**
 * 环向（切向）文字 —— 沿圆周方向书写。
 * 下半圈翻转，避免倒写。
 */
function tangentialText(cx, cy, r, deg, text, opts) {
  const o = opts || {};
  const flip = deg > 180;
  const rot = -deg + 90 + (flip ? 180 : 0);
  const p = polar(cx, cy, r, deg);
  return `<text x="${p.x.toFixed(2)}" y="${p.y.toFixed(2)}"`
       + ` transform="rotate(${rot.toFixed(2)} ${p.x.toFixed(2)} ${p.y.toFixed(2)})"`
       + ` text-anchor="middle" dominant-baseline="${o.baseline || 'middle'}"`
       + ` font-size="${o.size || 12}" fill="${o.fill || '#8a8272'}"`
       + ` font-family="${o.font || FONT}"`
       + (o.ls ? ` letter-spacing="${o.ls}"` : '')
       + (o.weight ? ` font-weight="${o.weight}"` : '')
       + (o.opacity != null ? ` opacity="${o.opacity}"` : '')
       + `>${esc(text)}</text>`;
}

/**
 * 把一圈角度互相推开，保证相邻间隔不小于 minSep。
 * 用于行星标签 —— 月亮与土星可以只差 1°，不推开就完全叠在一起。
 * 标记点仍画在【真实黄经】上，只有标签被挪动，所以位置不会被伪造。
 */
function spreadAngles(angles, minSep) {
  const n = angles.length;
  if (n < 2) return angles.slice();
  const a = angles.slice();
  for (let iter = 0; iter < 400; iter++) {
    let moved = false;
    for (let i = 0; i < n; i++) {
      const j = (i + 1) % n;
      let d = ((a[j] - a[i]) % 360 + 360) % 360;
      if (d < minSep) {
        const push = (minSep - d) / 2;
        a[i] -= push; a[j] += push;
        moved = true;
      }
    }
    if (!moved) break;
  }
  return a;
}

/* ==================================================================
 * 二、常量
 * ================================================================== */

const CX = 600, CY = 600;

// 九层同心环的半径（自外向内，环间留 4px 空隙）
const R = {
  outer: 588,
  beastOut: 588, beastIn: 558,
  dayunOut: 554, dayunIn: 486,
  xiuOut: 482, xiuIn: 418,
  zodOut: 414, zodIn: 370,
  jieOut: 366, jieIn: 338,
  planetOut: 334, planetIn: 294,
  zhiOut: 290, zhiIn: 230,
  palaceOut: 226, palaceIn: 112,
  core: 108,
};

const ZHI = ['子', '丑', '寅', '卯', '辰', '巳', '午', '未', '申', '酉', '戌', '亥'];
const ZHI_START = 255;            // 子宫起点黄经（255°–285°，居中于冬至 270°）
const ZHI_ANIMAL = { 子: '鼠', 丑: '牛', 寅: '虎', 卯: '兔', 辰: '龙', 巳: '蛇',
                     午: '马', 未: '羊', 申: '猴', 酉: '鸡', 戌: '狗', 亥: '猪' };
// 月建：寅 = 正月（立春起）
const ZHI_MONTH = { 寅: '正月', 卯: '二月', 辰: '三月', 巳: '四月', 午: '五月', 未: '六月',
                    申: '七月', 酉: '八月', 戌: '九月', 亥: '十月', 子: '十一月', 丑: '十二月' };
// 地支五行
const ZHI_WX = { 子: '水', 丑: '土', 寅: '木', 卯: '木', 辰: '土', 巳: '火',
                 午: '火', 未: '土', 申: '金', 酉: '金', 戌: '土', 亥: '水' };

const SIGNS = ['白羊', '金牛', '双子', '巨蟹', '狮子', '处女',
               '天秤', '天蝎', '射手', '摩羯', '水瓶', '双鱼'];
const SIGN_GLYPH = ['♈', '♉', '♊', '♋', '♌', '♍', '♎', '♏', '♐', '♑', '♒', '♓'];

// 二十四节气：索引 i 对应太阳黄经 i × 15°（春分 = 0°）
const JIE_QI = ['春分', '清明', '谷雨', '立夏', '小满', '芒种', '夏至', '小暑', '大暑', '立秋', '处暑', '白露',
                '秋分', '寒露', '霜降', '立冬', '小雪', '大雪', '冬至', '小寒', '大寒', '立春', '雨水', '惊蛰'];
// 节（月建分界，位于地支宫起点）；其余为气（位于地支宫正中）
const JIE_NAMES = ['清明', '立夏', '芒种', '小暑', '立秋', '白露', '寒露', '立冬', '大雪', '小寒', '立春', '惊蛰'];

const PLANET_GLYPH = { 太阳: '☉', 月亮: '☽', 水星: '☿', 金星: '♀',
                       火星: '♂', 木星: '♃', 土星: '♄', 上升: '升' };

const WX_COLOR = { 木: '#5fae7a', 火: '#d4604a', 土: '#c9a45c', 金: '#cfc7b6', 水: '#6b93d6' };
const GAN_WX = { 甲: '木', 乙: '木', 丙: '火', 丁: '火', 戊: '土', 己: '土',
                 庚: '金', 辛: '金', 壬: '水', 癸: '水' };

const GOLD = '#c9a227';
const GOLD_HI = '#f0d98a';
const GOLD_MID = '#e8c96a';
const PAPER = '#e8dfc8';
const MUTED = '#8a8272';
const FAINT = '#5f5a4e';
const ZHU = '#d4604a';
const TEAL = '#3f9e83';

/* ==================================================================
 * 三、主绘制
 * ================================================================== */

/**
 * @param {object} f  事实层 JSON（mingli.fact/1）
 * @returns {string}  SVG 字符串
 */
function buildPlate(f) {
  const ascLon = f.astro.ascendant.longitude;
  // 黄经 → 屏幕角：上升点固定在 9 点钟（180°），黄经沿逆时针递增
  const th = (lon) => 180 + (lon - ascLon);

  const out = [];
  out.push(`<svg viewBox="0 0 1200 1200" width="1200" height="1200" xmlns="http://www.w3.org/2000/svg" class="plate" role="img"`
         + ` aria-label="${esc(f.input.y + '年' + f.input.m + '月' + f.input.d + '日命盘天图')}">`);

  /* ── defs ── */
  out.push(`<defs>
    <radialGradient id="sky" cx="50%" cy="50%" r="50%">
      <stop offset="0%" stop-color="#1c1830"/>
      <stop offset="42%" stop-color="#12101e"/>
      <stop offset="78%" stop-color="#0a0912"/>
      <stop offset="100%" stop-color="#050409"/>
    </radialGradient>
    <radialGradient id="coreGlow" cx="50%" cy="50%" r="50%">
      <stop offset="0%" stop-color="#c9a227" stop-opacity=".26"/>
      <stop offset="70%" stop-color="#c9a227" stop-opacity=".05"/>
      <stop offset="100%" stop-color="#c9a227" stop-opacity="0"/>
    </radialGradient>
    <radialGradient id="halo" cx="50%" cy="50%" r="50%">
      <stop offset="55%" stop-color="#c9a227" stop-opacity="0"/>
      <stop offset="86%" stop-color="#c9a227" stop-opacity=".07"/>
      <stop offset="100%" stop-color="#c9a227" stop-opacity="0"/>
    </radialGradient>
    <filter id="glow" x="-60%" y="-60%" width="220%" height="220%">
      <feGaussianBlur stdDeviation="2.6" result="b"/>
      <feMerge><feMergeNode in="b"/><feMergeNode in="SourceGraphic"/></feMerge>
    </filter>
    <filter id="softglow" x="-60%" y="-60%" width="220%" height="220%">
      <feGaussianBlur stdDeviation="10"/>
    </filter>
  </defs>`);

  out.push(`<rect width="1200" height="1200" fill="url(#sky)"/>`);

  /* ── 星野（确定性伪随机：同一张盘每次完全一样）── */
  out.push(`<g id="starfield" opacity=".5">`);
  let seed = 20260515;
  const rnd = () => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed / 0x7fffffff; };
  for (let i = 0; i < 300; i++) {
    const a = rnd() * TAU, rr = 24 + rnd() * 566;
    const x = CX + rr * Math.cos(a), y = CY + rr * Math.sin(a);
    const s = rnd() * 1.4 + 0.35;
    out.push(`<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="${s.toFixed(2)}"`
           + ` fill="#e8dfc8" opacity="${(0.12 + rnd() * 0.55).toFixed(2)}"/>`);
  }
  out.push(`</g>`);

  /* ── 底层光晕 ── */
  out.push(`<circle cx="${CX}" cy="${CY}" r="${R.xiuOut - 10}" fill="none"`
         + ` stroke="#c9a227" stroke-opacity=".10" stroke-width="40" filter="url(#softglow)"/>`);
  out.push(`<circle cx="${CX}" cy="${CY}" r="470" fill="url(#halo)"/>`);

  /* ── 逐层 ── */
  out.push(drawBeast(f, th));
  out.push(drawDaYun(f, th));
  out.push(drawXiSu(f, th));
  out.push(drawZodiac(f, th));
  out.push(drawJieQi(f, th));
  out.push(drawPlanets(f, th));
  out.push(drawZhi(f, th));
  out.push(drawPalaces(f, th));
  out.push(drawCore(f));
  out.push(drawFrame(f, th));

  out.push(`</svg>`);
  return out.join('\n');
}

/* ── ① 四象带 ── */
function drawBeast(f, th) {
  const g = [`<g id="beast">`];
  const groups = [];
  f.astro.xiSu.forEach((x) => {
    const last = groups[groups.length - 1];
    if (last && last.beast === x.beast) { last.span += x.span; }
    else groups.push({ beast: x.beast, start: x.start, span: x.span });
  });

  groups.forEach((gp) => {
    const a1 = th(gp.start), a2 = a1 + gp.span, mid = (a1 + a2) / 2;
    const color = f.astro.xiSu.find((x) => x.beast === gp.beast).color;
    // 色带
    g.push(`<path d="${arcPath(CX, CY, R.beastOut - 14, a1, a2)}" fill="none"`
         + ` stroke="${color}" stroke-opacity=".5" stroke-width="5" stroke-linecap="butt"/>`);
    g.push(`<path d="${arcPath(CX, CY, R.beastOut - 24, a1, a2)}" fill="none"`
         + ` stroke="${color}" stroke-opacity=".18" stroke-width="1.2"/>`);
    // 名（环向，避免径向外溢）
    g.push(tangentialText(CX, CY, R.beastOut - 6, mid, gp.beast, {
      size: 12, fill: color, ls: 3, opacity: .92,
    }));
    // 与相邻象的分界
    g.push(radial(CX, CY, R.beastIn, R.beastOut - 4, a1, 'stroke="#c9a227" stroke-opacity=".3" stroke-width=".9"'));
  });
  g.push(`</g>`);
  return g.join('\n');
}

/* ── ② 大运环（十步，序列环）── */
function drawDaYun(f, th) {
  const g = [`<g id="dayun">`];
  const segs = f.bazi.yun.daYun.filter((s) => !s.isPreYun);
  if (!segs.length) { g.push(`</g>`); return g.join('\n'); }

  const n = segs.length, step = 360 / n;
  segs.forEach((s, i) => {
    const a1 = 90 - (i + 1) * step, a2 = 90 - i * step;
    const mid = (a1 + a2) / 2;
    const cur = s.isCurrent;
    g.push(`<path d="${sector(CX, CY, R.dayunIn, R.dayunOut - 4, a1, a2)}"`
         + ` fill="${GOLD}" fill-opacity="${cur ? '.10' : '.022'}"`
         + ` stroke="${cur ? GOLD_MID : GOLD}" stroke-opacity="${cur ? '.9' : '.18'}"`
         + ` stroke-width="${cur ? '1.5' : '.6'}"/>`);
    g.push(radialText(CX, CY, R.dayunIn + 20, mid, s.gz || '—', {
      size: cur ? 19 : 16, fill: cur ? GOLD_HI : GOLD,
      opacity: cur ? 1 : .6, weight: cur ? '600' : '',
    }));
    g.push(radialText(CX, CY, R.dayunIn + 48, mid, s.startYear + '', {
      size: 9, fill: cur ? PAPER : MUTED, opacity: cur ? .85 : .45,
    }));
    g.push(radial(CX, CY, R.dayunIn, R.dayunOut - 4, a1, 'stroke="#c9a227" stroke-opacity=".18" stroke-width=".6"'));
  });
  g.push(`</g>`);
  return g.join('\n');
}

/* ── ③ 二十八宿环 ── */
function drawXiSu(f, th) {
  const g = [`<g id="xisu">`];
  g.push(`<path d="${sector(CX, CY, R.xiuIn, R.xiuOut, 0, 359.999)}" fill="#c9a227" fill-opacity=".022"/>`);

  f.astro.xiSu.forEach((x) => {
    const a1 = th(x.start), a2 = a1 + x.span, mid = (a1 + a2) / 2;
    // 窄宿（觜 2 古度 ≈ 1.97°）字号必须自动缩小，否则会挤出宫格
    const size = x.span < 3 ? 11 : x.span < 6 ? 14 : x.span < 9 ? 16 : 19;
    g.push(`<path d="${sector(CX, CY, R.xiuIn, R.xiuOut, a1, a2)}"`
         + ` fill="${x.color}" fill-opacity=".10" stroke="${x.color}" stroke-opacity=".46" stroke-width=".8"/>`);
    g.push(`<title>${esc(x.name + '宿 · ' + x.du + ' 古度 · ' + x.beast + ' · 距星 ' + x.star)}</title>`);
    g.push(radialText(CX, CY, R.xiuIn + 22, mid, x.name, {
      size, fill: x.color, opacity: .96, weight: '600',
    }));
    if (x.span >= 6) {
      g.push(radialText(CX, CY, R.xiuIn + 46, mid, x.du + '度', {
        size: 9.5, fill: GOLD, opacity: .45,
      }));
    }
  });

  // 四象分界
  f.astro.xiSu.forEach((x, i) => {
    if (i === 0 || f.astro.xiSu[i - 1].beast !== x.beast) {
      g.push(radial(CX, CY, R.xiuIn, R.xiuOut, th(x.start), 'stroke="#e8dfc8" stroke-opacity=".45" stroke-width="1.1"'));
    }
  });
  g.push(`</g>`);
  return g.join('\n');
}

/* ── ④ 黄道十二宫环 ── */
function drawZodiac(f, th) {
  const g = [`<g id="zodiac">`];
  const sunSign = f.astro.sun.sign;
  SIGNS.forEach((s, i) => {
    const a1 = th(i * 30), a2 = a1 + 30, mid = a1 + 15;
    const isSun = s === sunSign;
    g.push(`<path d="${sector(CX, CY, R.zodIn, R.zodOut, a1, a2)}"`
         + ` fill="${isSun ? GOLD : '#ffffff'}" fill-opacity="${isSun ? '.09' : '.012'}"`
         + ` stroke="${GOLD}" stroke-opacity="${isSun ? '.55' : '.24'}" stroke-width="${isSun ? '1' : '.6'}"/>`);
    g.push(radialText(CX, CY, R.zodIn + 13, mid, s, {
      size: 13, fill: isSun ? GOLD_HI : PAPER, opacity: isSun ? 1 : .85, weight: '600',
    }));
    g.push(hText(CX, CY, R.zodOut - 11, mid, SIGN_GLYPH[i], {
      size: 16, fill: isSun ? GOLD_MID : MUTED, opacity: isSun ? 1 : .6,
      font: 'Apple Symbols, Segoe UI Symbol, serif',
    }));
    // 每 5° 一格刻度
    for (let k = 0; k < 6; k++) {
      const long = k === 0;
      g.push(radial(CX, CY, R.zodOut - (long ? 9 : 4), R.zodOut, a1 + k * 5,
        `stroke="#c9a227" stroke-opacity="${long ? '.42' : '.16'}" stroke-width="${long ? '.9' : '.55'}"`));
    }
  });
  g.push(`</g>`);
  return g.join('\n');
}

/* ── ⑤ 二十四节气环 ── */
function drawJieQi(f, th) {
  const g = [`<g id="jieqi">`];
  const sunLon = f.astro.sun.longitude;
  // 当前所处节气区间高亮
  const idx = Math.floor(((sunLon % 360) + 360) % 360 / 15);
  JIE_QI.forEach((name, i) => {
    const lon = i * 15;
    const a1 = th(lon), mid = a1 + 7.5;
    const isJie = JIE_NAMES.includes(name);
    const cur = i === idx;
    if (cur) {
      g.push(`<path d="${sector(CX, CY, R.jieIn, R.jieOut, a1, a1 + 15)}"`
           + ` fill="${GOLD}" fill-opacity=".13" stroke="${GOLD_MID}" stroke-opacity=".5" stroke-width=".7"/>`);
    }
    g.push(radial(CX, CY, R.jieOut - (isJie ? 12 : 6), R.jieOut, a1,
      `stroke="#c9a227" stroke-opacity="${isJie ? '.45' : '.22'}" stroke-width="${isJie ? '.9' : '.55'}"`));
    g.push(radialText(CX, CY, R.jieIn + 14, mid, name, {
      size: 9.5, fill: cur ? GOLD_HI : (isJie ? PAPER : MUTED),
      opacity: cur ? 1 : (isJie ? .72 : .46), weight: cur ? '600' : '',
    }));
  });
  g.push(`</g>`);
  return g.join('\n');
}

/* ── ⑥ 七星带 ── */
function drawPlanets(f, th) {
  const g = [`<g id="planets">`];
  const bodies = f.astro.bodies.concat([f.astro.ascendant]);
  const sorted = bodies.slice().sort((a, b) => a.longitude - b.longitude);
  const trueAngles = sorted.map((b) => th(b.longitude));
  const shown = spreadAngles(trueAngles, 10);

  // 轨道参考圈
  g.push(`<circle cx="${CX}" cy="${CY}" r="${R.planetIn}" fill="none" stroke="#c9a227" stroke-opacity=".1" stroke-width=".6" stroke-dasharray="2 5"/>`);
  g.push(`<circle cx="${CX}" cy="${CY}" r="${R.planetOut}" fill="none" stroke="#c9a227" stroke-opacity=".1" stroke-width=".6" stroke-dasharray="2 5"/>`);

  sorted.forEach((b, i) => {
    const aTrue = trueAngles[i], aShow = shown[i];
    const isAsc = b.name === '上升';
    const col = isAsc ? GOLD_MID : (b.edge ? '#e0a060' : PAPER);
    // 真实黄经刻度 —— 标签被推开时，位置的真伪由这根线交代
    g.push(radial(CX, CY, R.planetIn, R.planetOut, aTrue,
      `stroke="${col}" stroke-opacity="${isAsc ? '.55' : '.22'}" stroke-width="${isAsc ? '1.1' : '.7'}"`));
    const p = polar(CX, CY, R.planetOut - 4, aTrue);
    g.push(`<circle cx="${p.x.toFixed(1)}" cy="${p.y.toFixed(1)}" r="${isAsc ? 4.2 : 2.9}" fill="${col}" filter="url(#glow)"/>`);
    // 标签
    const glyph = PLANET_GLYPH[b.name] || '';
    g.push(radialText(CX, CY, (R.planetIn + R.planetOut) / 2, aShow, glyph + b.name, {
      size: isAsc ? 12.5 : 11.5, fill: col, opacity: isAsc ? 1 : .9,
      weight: isAsc ? '600' : '', font: FONT,
    }));
    g.push(`<title>${esc(b.name + ' 黄经 ' + b.longitude + '°　' + b.sign + ' ' + b.degInSign + '°'
      + (b.edge ? '　⚠ 距星座边界小于自身误差上限' : ''))}</title>`);
  });

  // 上升—下降轴线
  const ascA = th(f.astro.ascendant.longitude);
  g.push(`<line x1="${polar(CX, CY, R.palaceOut + 2, ascA).x.toFixed(1)}" y1="${polar(CX, CY, R.palaceOut + 2, ascA).y.toFixed(1)}"`
       + ` x2="${polar(CX, CY, R.palaceOut + 2, ascA + 180).x.toFixed(1)}" y2="${polar(CX, CY, R.palaceOut + 2, ascA + 180).y.toFixed(1)}"`
       + ` stroke="${GOLD_MID}" stroke-opacity=".28" stroke-width=".9" stroke-dasharray="6 6"/>`);
  g.push(`</g>`);
  return g.join('\n');
}

/* ── ⑦ 十二地支环 ── */
function drawZhi(f, th) {
  const g = [`<g id="zhi">`];
  const soulBranch = f.ziwei.soulPalaceBranch;
  ZHI.forEach((z, i) => {
    const lon0 = ZHI_START + i * 30;
    const a1 = th(lon0), a2 = a1 + 30, mid = a1 + 15;
    const isSoul = z === soulBranch;
    g.push(`<path d="${sector(CX, CY, R.zhiIn, R.zhiOut, a1, a2)}"`
         + ` fill="${GOLD}" fill-opacity="${isSoul ? '.12' : '.025'}"`
         + ` stroke="${GOLD}" stroke-opacity="${isSoul ? '.55' : '.2'}" stroke-width="${isSoul ? '1.1' : '.6'}"/>`);
    g.push(`<title>${esc(z + '宫 · ' + ZHI_MONTH[z] + '月建 · ' + ZHI_WX[z] + (isSoul ? ' · 命宫所在' : ''))}</title>`);
    g.push(hText(CX, CY, R.zhiIn + 12, mid, ZHI_MONTH[z], { size: 9, fill: MUTED, opacity: .5 }));
    g.push(hText(CX, CY, R.zhiIn + 34, mid, z, {
      size: 28, fill: isSoul ? GOLD_HI : PAPER, opacity: isSoul ? 1 : .8, weight: '600',
    }));
    g.push(hText(CX, CY, R.zhiIn + 54, mid, ZHI_ANIMAL[z], { size: 9.5, fill: MUTED, opacity: .55 }));
    g.push(radial(CX, CY, R.zhiIn, R.zhiOut, a1, 'stroke="#c9a227" stroke-opacity=".16" stroke-width=".6"'));
  });
  g.push(`</g>`);
  return g.join('\n');
}

/* ── ⑧ 紫微十二宫环 ── */
function drawPalaces(f, th) {
  const g = [`<g id="palaces">`];
  const byBranch = {};
  f.ziwei.palaces.forEach((p) => { byBranch[p.earthlyBranch] = p; });
  const soulBranch = f.ziwei.soulPalaceBranch;

  ZHI.forEach((z, i) => {
    const lon0 = ZHI_START + i * 30;
    const a1 = th(lon0), a2 = a1 + 30, mid = a1 + 15;
    const p = byBranch[z];
    if (!p) return;
    const isSoul = p.name === '命宫';
    const isBody = p.isBodyPalace;

    // 命宫：额外一层柔光，把视线先拉过去
    if (isSoul) {
      g.push(`<path d="${sector(CX, CY, R.palaceIn - 10, R.palaceOut + 6, a1 + 3, a2 - 3)}"`
           + ` fill="${GOLD}" fill-opacity=".10" filter="url(#softglow)"/>`);
    }

    g.push(`<path d="${sector(CX, CY, R.palaceIn, R.palaceOut, a1 + 1.1, a2 - 1.1)}"`
